"""Contract compliance: the API generated by FastAPI must match docs/api/openapi.yaml.

Every path and method the code exposes must be in the contract. For request bodies and
2xx JSON responses, object property names must match recursively (nested objects, array
items, nullable unions); an object declared with fields on one side only is a difference.
Endpoints in the contract that are not implemented yet are allowed (contract-first).
Exit code 1 lists every difference.
"""

import os
import sys
from pathlib import Path
from typing import Any

import yaml

Schema = dict[str, Any]
METHODS = ("get", "put", "post", "patch", "delete")


def resolve(schema: Schema | None, spec: Schema) -> Schema:
    """Follow $ref and merge allOf so that object properties can be compared."""
    if not schema:
        return {}
    if "$ref" in schema:
        node: Any = spec
        for part in schema["$ref"].removeprefix("#/").split("/"):
            node = node[part]
        return resolve(node, spec)
    if "allOf" in schema:
        merged: Schema = {"properties": {}}
        for sub in schema["allOf"]:
            merged["properties"].update(resolve(sub, spec).get("properties", {}))
        return merged
    return schema


def json_schema(container: Schema | None, spec: Schema) -> Schema:
    content = (container or {}).get("content", {})
    for media, body in content.items():
        if media.endswith("json"):
            return resolve(body.get("schema"), spec)
    return {}


def unwrap(schema: Schema, spec: Schema) -> Schema:
    """Resolve refs and pick the non-null branch of nullable unions (anyOf/oneOf with null)."""
    schema = resolve(schema, spec)
    for key in ("anyOf", "oneOf"):
        branches = [resolve(b, spec) for b in schema.get(key, [])]
        typed = [b for b in branches if b.get("type") != "null" and b]
        if len(typed) == 1:
            return unwrap(typed[0], spec)
    return schema


MAX_DEPTH = 8


def compare_schemas(
    label: str,
    code: Schema,
    contract: Schema,
    code_spec: Schema,
    contract_spec: Schema,
    depth: int = 0,
) -> list[str]:
    """Compare object property names recursively (nested objects and array items)."""
    if depth > MAX_DEPTH:
        return []
    code, contract = unwrap(code, code_spec), unwrap(contract, contract_spec)
    errors: list[str] = []
    code_props, contract_props = code.get("properties"), contract.get("properties")
    if contract_props and not code_props:
        errors.append(
            f"{label}: code does not declare fields ({', '.join(sorted(contract_props))})"
        )
    elif code_props and not contract_props:
        errors.append(
            f"{label}: contract does not declare fields ({', '.join(sorted(code_props))})"
        )
    elif code_props and contract_props:
        if extra := sorted(set(code_props) - set(contract_props)):
            errors.append(f"{label}: fields not in contract: {', '.join(extra)}")
        if missing := sorted(set(contract_props) - set(code_props)):
            errors.append(f"{label}: contract fields missing in code: {', '.join(missing)}")
        for name in sorted(set(code_props) & set(contract_props)):
            errors += compare_schemas(
                f"{label}.{name}",
                code_props[name],
                contract_props[name],
                code_spec,
                contract_spec,
                depth + 1,
            )
    if "items" in code and "items" in contract:
        errors += compare_schemas(
            f"{label}[]", code["items"], contract["items"], code_spec, contract_spec, depth + 1
        )
    return errors


def compare(code_spec: Schema, contract_spec: Schema) -> list[str]:
    errors: list[str] = []
    contract_paths = contract_spec.get("paths", {})
    for path, code_item in code_spec.get("paths", {}).items():
        contract_item = contract_paths.get(path)
        if contract_item is None:
            errors.append(f"{path}: path not in contract")
            continue
        for method in METHODS:
            if method not in code_item:
                continue
            label = f"{method.upper()} {path}"
            contract_op = contract_item.get(method)
            if contract_op is None:
                errors.append(f"{label}: method not in contract")
                continue
            code_op = code_item[method]
            errors += compare_schemas(
                f"{label} request",
                json_schema(code_op.get("requestBody"), code_spec),
                json_schema(contract_op.get("requestBody"), contract_spec),
                code_spec,
                contract_spec,
            )
            for status, response in code_op.get("responses", {}).items():
                if not status.startswith("2"):
                    continue
                contract_response = contract_op.get("responses", {}).get(status)
                if contract_response is None:
                    errors.append(f"{label} {status}: response status not in contract")
                    continue
                contract_response = resolve(contract_response, contract_spec)
                errors += compare_schemas(
                    f"{label} {status} response",
                    json_schema(response, code_spec),
                    json_schema(contract_response, contract_spec),
                    code_spec,
                    contract_spec,
                )
    return errors


def main() -> int:
    from app.main import app

    contract_path = Path(os.environ.get("CONTRACT_PATH", "/contract/openapi.yaml"))
    contract = yaml.safe_load(contract_path.read_text(encoding="utf-8"))
    errors = compare(app.openapi(), contract)
    if errors:
        print(f"API differs from {contract_path}:")
        for error in errors:
            print(f"  - {error}")
        return 1
    print(f"API matches {contract_path} ({len(app.openapi()['paths'])} implemented paths).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
